/** Precision and engineering workspaces. No network service, model upload or framework. */
import {ExactClient,solidFromExact,exactInput,exactFaceIndex} from './exact-client.js';
import {M,V,transformedPoint} from '../core/math.js';
import {Solid,Polygon} from '../core/kernel.js';
import {uid,ModelDocument} from '../core/document.js';
import {download as nativeDownload} from '../core/io.js';
const download=(name,data,type)=>nativeDownload(data,name,type);
import {assemblyReference,solveAssembly,applyAssemblySolution} from './assembly.js';
import {sheetLayout,sheetSVG,sheetDXF,sheetBendCSV} from './sheet-metal.js';
import {CHARACTERISTICS,createAnnotation,resolveAnnotation,annotationValue,featureControlText,engineeringDrawing,pmiJSON} from './pmi.js';
import {preflight,transformedExactProperties,bomCSV,surfaceVTK,shellINP} from './preflight.js';
const escape=s=>String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'}[c]));
const json=(value)=>JSON.stringify(value,null,2);
const textArea=(name,label,value,rows=7)=>`<label class="field engineering-json"><span>${escape(label)}</span><textarea id="f-${name}" name="${name}" rows="${rows}" spellcheck="false">${escape(typeof value==='string'?value:json(value))}</textarea></label>`;
const readJSON=(data,key)=>{const s=data.get(key);if(typeof s!=='string'||s.length>250000)throw Error('JSON input exceeds the editor budget.');try{return JSON.parse(s);}catch{throw Error(`${key}: enter valid JSON.`);}};
const vec=(s)=>{const a=String(s).split(/[ ,;]+/).filter(Boolean).map(Number);if(a.length!==3||a.some(x=>!Number.isFinite(x)||Math.abs(x)>1e7))throw Error('Enter three finite coordinates separated by commas.');return a;};
const indices=s=>{if(!String(s).trim())return [];const a=String(s).split(/[ ,;]+/).filter(Boolean).map(Number);if(a.some(x=>!Number.isInteger(x)||x<0))throw Error('Use zero-based integer topology indices.');return [...new Set(a)];};
const note=s=>`<div class="note">${s}</div>`;
const warning=s=>`<div class="note warning">${s}</div>`;
const table=(heads,rows)=>`<div class="engineering-table-wrap"><table class="engineering-table"><thead><tr>${heads.map(x=>`<th>${escape(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${escape(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const defaultSurface={uDegree:3,vDegree:3,uKnots:[0,1],vKnots:[0,1],uMultiplicities:[4,4],vMultiplicities:[4,4],poles:Array.from({length:4},(_,i)=>Array.from({length:4},(_,j)=>[(i-1.5)*20,(j-1.5)*15,((i===1||i===2)&&(j===1||j===2))?20:0])),weights:Array.from({length:4},()=>[1,1,1,1])};
const defaultSheet={width:50,thickness:2,kFactor:.42,radius:3,lengths:[35,50,35],bends:[90,-90],holes:[{segment:1,along:15,across:0,radius:4},{segment:1,along:35,across:0,radius:4}]};
const defaultLoft=[{type:'circle',radius:18,plane:'XY',origin:0},{type:'ellipse',rx:25,ry:13,plane:'XY',origin:22},{type:'circle',radius:12,plane:'XY',origin:48}];
const profileDefault={type:'rectangle',width:40,height:25,plane:'XY',origin:0};
await new Promise(resolve=>{const poll=()=>window.avolith?.ready?resolve():setTimeout(poll,25);poll();});
const app=window.avolith,{modal,field,fgrid,val,toast,status,closeModal}=app.ui;
const client=new ExactClient(),iges=new ExactClient(new URL('./iges-worker.js',import.meta.url));
const selected=()=>app.ui.selectedBodies();
const one=(exact=true)=>{const bs=selected();if(bs.length!==1)throw Error('Select one body.');if(bs[0].locked)throw Error('Unlock the body before editing.');if(exact)exactInput(bs[0]);return bs[0];};
const chosenExact=(count=1)=>{const bs=selected();if(bs.length<count)throw Error(`Select at least ${count} exact bodies.`);for(const b of bs){if(b.locked)throw Error('Unlock the selected bodies first.');exactInput(b);}return bs;};
const allExact=()=>{const bs=selected().length?selected():app.document.visible();if(!bs.length)throw Error('Create or select exact geometry first.');bs.forEach(exactInput);return bs;};
let lastDrawing='',lastSolve=null,showPMI=true;
const banner=document.createElement('div');banner.className='precision-state';banner.innerHTML='<span class="precision-dot"></span><span class="precision-state-label">Exact kernel · on demand</span><button type="button" data-cmd="exact-cancel" hidden>Cancel</button>';
document.querySelector('.workspace-label')?.replaceWith(banner);
function kernelState(){const busy=client.busy||iges.busy;banner.classList.toggle('busy',busy);banner.querySelector('.precision-state-label').textContent=busy?'Computing exact geometry…':client.ready?'B-rep kernel ready':'Exact kernel · on demand';banner.querySelector('button').hidden=!busy;}
client.addEventListener('change',kernelState);iges.addEventListener('change',kernelState);
function cancel(){client.cancel();iges.cancel();}
function guard(){const document=app.document,revision=document.revision;return ()=>{if(document!==app.document||revision!==document.revision)throw Error('The document changed during this operation. The result was discarded; newer edits are safe.');};}
async function query(command,args={},worker=client){status(command+'… · Esc to cancel',true);try{return await worker.run(command,args);}finally{status('Ready');}}
async function run(command,args={},label='Exact '+command,apply=null){const check=guard(),result=await query(command,args);check();if(apply){app.document.transact(label,()=>apply(result));app.invalidate();}return result;}
async function create(command,args,name){let id;await run(command,args,'Create '+name,p=>{const d=app.document;if(!d.components.length)d.components.push({id:'parts',name:'Parts'});id=d.add(solidFromExact(p),name,'aluminum',d.components[0].id).id;});app.setSelection([id]);app.renderer.camera.fit(app.document.bounds());app.renderer.request();return app.document.find(id);}
async function modify(b,command,args,label='Exact '+command){const id=b.id;await run(command,{...args,shape:exactInput(b)},label,p=>{const body=app.document.find(id);if(!body||body.locked)throw Error('The target is no longer editable.');body.solid=solidFromExact(p);});app.setSelection([id]);return app.document.find(id);}
function report(title,html){modal(title,html,null,'Close',true);}
function pickedFace(b){return exactFaceIndex(app.state,b);}
function pickedEdge(b){const edge=app.state.edge,e=b.solid.meta.exact;if((edge?.body?.id||edge?.body)!==b.id||!e)return null;const mid=V.mul(V.add(...edge.points),.5);let best=Infinity,index=null;for(const g of e.edgeGroups){for(let k=g.start*3;k<(g.start+g.count)*3;k+=6){const a=transformedPoint(e.pose,e.edgeLines.slice(k,k+3)),z=transformedPoint(e.pose,e.edgeLines.slice(k+3,k+6)),d=V.dist(mid,V.mul(V.add(a,z),.5));if(d<best){best=d;index=g.index;}}}return index;}
function selectionFields(b,kind){const e=b.solid.meta.exact,id=kind==='faces'?pickedFace(b):pickedEdge(b);return field(kind,`${kind==='faces'?'Face':'Edge'} indices (zero-based)`,id??'',{type:'text',optional:kind==='edges'})+`<div class="small-note">${e.faces.length} faces · ${e.edges.length} edges. ${kind==='edges'?'Leave empty to process every edge.':'Select a face in the viewport, or enter its index.'} Use Inspect B-rep for the topology table.</div>`;}
function primitiveDialog(){modal('Create an exact analytic solid',`${note('The model stores OpenCascade B-rep geometry. The display mesh is regenerated from the solid; it is not the modeling source.')}${field('kind','Primitive','box',{options:['box','cylinder','sphere','cone','torus','tube']})}${fgrid(field('width','Box width',40,{min:.001}),field('depth','Box depth',30,{min:.001}),field('height','Height',25,{min:.001}))}${fgrid(field('radius','Radius / outer radius',18,{min:.001}),field('secondary','Top / inner / minor radius',6,{min:0}))}${field('center','Center X, Y, Z (mm)','0, 0, 20',{type:'text'})}`,async d=>{const kind=d.get('kind'),radius=val(d,'radius',.001),secondary=val(d,'secondary',0);await create('primitive',{kind,parameters:{width:val(d,'width',.001),depth:val(d,'depth',.001),height:val(d,'height',.001),radius,topRadius:secondary,outer:radius,inner:secondary,major:radius,minor:secondary,center:vec(d.get('center'))}},'Exact '+kind);},'Create exact solid');}
async function promote(){const b=one(false),m=b.solid.meta;if(m.exact){toast('This body already has an exact B-rep.');return;}if(!['box','cylinder','sphere','cone','torus','tube'].includes(m.type)||m.r>0)throw Error('Only retained, unrounded analytic primitives can be promoted without reconstructing their design intent. Import STEP/IGES or use Planar B-rep for other meshes.');modal('Rebuild retained primitive as exact CAD',note(`Rebuild <strong>${escape(b.name)}</strong> from its retained ${escape(m.type)} parameters. No curve fitting is inferred from a mesh.`),async()=>{const parameters={...m,width:m.w,depth:m.d,height:m.h??m.height,topRadius:m.r2};await run('primitive',{kind:m.type,parameters},'Promote primitive',p=>{app.document.find(b.id).solid=solidFromExact(p);});app.setSelection([b.id]);},'Promote');}
function planarBrep(){const b=one(false);if(b.solid.meta.exact)throw Error('This body is already exact.');modal('Convert mesh to planar B-rep',warning('Each polygon becomes an exact planar face. This does NOT recover circles, NURBS or the original design. Closed, conforming meshes only; at most 5,000 polygons.')+note(`${b.solid.polygons.length} source polygons`),async()=>{await run('facetBrep',{polygons:b.solid.polygons.map(p=>p.vertices)},'Planar B-rep reconstruction',p=>{app.document.find(b.id).solid=solidFromExact(p);});app.setSelection([b.id]);},'Convert planar faces');}
function tessellate(){const b=one();modal('Explicitly convert exact body to facets',warning('This replaces the editable B-rep with its current display mesh. Subsequent operations use the faceted kernel. Undo restores the exact body. Mates and PMI referencing the previous topology will become stale.'),()=>{app.document.transact('Convert exact body to facets',()=>{app.document.find(b.id).solid=new Solid(b.solid.polygons.map(p=>new Polygon(p.vertices,p.id)),{type:'mesh',source:'explicit exact-to-facet conversion'});});app.setSelection([b.id]);},'Convert to facets');}
function surfaceDialog(){const b=selected().length===1?selected()[0]:null,e=b?.solid.meta.exact;const def=e?.surfaceDefinition||defaultSurface;modal(e?.surfaceDefinition?'Edit NURBS control net':'Create a rational NURBS surface',note('Edit degrees, distinct knots, multiplicities, control points and positive weights. The boundary is the full nonperiodic UV domain. Arbitrary trim loops are not part of this editor.')+textArea('surface','NURBS definition',def,15),async d=>{const spec=readJSON(d,'surface');if(e?.surfaceDefinition){if(b.locked)throw Error('Unlock the body.');const check=guard();const p=await query('nurbs',spec);const surfacePose=M.mul(e.pose,e.surfacePose||M.identity()),placed=await query('transform',{shape:p,matrix:surfacePose});check();app.document.transact('Edit NURBS surface',()=>app.document.find(b.id).solid=solidFromExact({...placed,surfaceDefinition:spec,surfacePose}));app.setSelection([b.id]);}else await create('nurbs',spec,'NURBS surface');},e?.surfaceDefinition?'Update surface':'Create surface',true);}
function profileFromSelection(){const sk=app.document.sketches.find(s=>s.id===app.state.selectedSketch);if(!sk)return profileDefault;if(!sk.closed)throw Error('Finish a closed sketch profile first.');return {type:'polygon',points:sk.points,plane:sk.plane,origin:sk.origin};}
function profileDialog(command){const revolve=command==='revolve',profile=revolve?{points:[[8,0],[20,0],[20,8],[14,8],[14,28],[8,28]],plane:'XZ',origin:0}:profileFromSelection();modal('Exact '+command,note('Polygon profiles preserve their straight edges. Use type circle or ellipse for analytic curves; a previously faceted circle sketch remains a polygon.')+textArea('profile','Profile definition',profile,9)+(revolve?fgrid(field('angle','Angle (degrees)',360,{min:.001,max:360}),field('axis','World axis','0,0,1',{type:'text'}))+field('origin','Axis origin','0,0,0',{type:'text'}):fgrid(field('distance','Signed distance (mm)',25),field('endFactor','End scale',1,{min:.001}),field('twist','Twist (degrees)',0))),async d=>{const args={profile:readJSON(d,'profile')};if(revolve)Object.assign(args,{angle:val(d,'angle',.001,360),axis:vec(d.get('axis')),origin:vec(d.get('origin'))});else Object.assign(args,{distance:val(d,'distance'),endFactor:val(d,'endFactor',.001),twist:val(d,'twist',-3600,3600)});await create(command,args,'Exact '+command);},'Create',true);}
function loftDialog(){modal('Exact profile loft',note('Sections are analytic sketches. Enable ruled for straight generators or surface for an open shell.')+textArea('profiles','Ordered profiles',defaultLoft,12)+fgrid(field('ruled','Ruled loft',false,{type:'checkbox',inline:true}),field('surface','Open surface',false,{type:'checkbox',inline:true})),async d=>create('loft',{profiles:readJSON(d,'profiles'),ruled:d.has('ruled'),surface:d.has('surface')},'Exact loft'),'Loft',true);}
function sweepDialog(){modal('Exact circular sweep',note('A circular section follows a piecewise-linear 3D path with round transitions. The kernel rejects incompatible or self-intersecting configurations.')+textArea('path','Path points in millimetres',[[0,0,0],[0,0,25],[20,0,40],[40,15,40]],8)+field('radius','Section radius',3,{min:.001}),async d=>create('sweep',{path:readJSON(d,'path'),radius:val(d,'radius',.001)},'Exact sweep'),'Sweep');}
function edgeDialog(command){const b=one();modal(command==='fillet'?'Exact edge fillet':'Exact edge chamfer',note('Uses the analytic solid and its topological edges. Unsupported intersections or excessive radii are rejected without changing the document.')+selectionFields(b,'edges')+field('radius',command==='fillet'?'Rolling-ball radius (mm)':'Equal chamfer distance (mm)',2,{min:.001}),d=>modify(b,command,{edges:indices(d.get('edges')),radius:val(d,'radius',.001)}),'Apply');}
function faceDialog(command){const b=one(),names={shell:'Remove faces and shell',draft:'Draft selected faces',offsetSurface:'Offset an analytic surface',faceExtrude:'Pull an exact planar face'};const valueName=command==='shell'?'thickness':command==='draft'?'angle':'distance';modal(names[command],note(command==='shell'?'Negative thickness offsets inward; positive thickness offsets outward. Selected faces are openings.':command==='faceExtrude'?'Extrudes the selected planar face as a prism, then unions or subtracts material. This is not unrestricted movement of curved faces.':'The operation is computed from analytic geometry and verified before committing.')+selectionFields(b,'faces')+field(valueName,command==='draft'?'Draft angle (degrees)':command==='shell'?'Signed wall thickness (mm)':'Signed distance (mm)',command==='shell'?-2:3)+(command==='draft'?field('plane','Neutral plane','XY',{options:['XY','XZ','YZ']}):''),d=>modify(b,command,{faces:indices(d.get('faces')),[valueName]:val(d,valueName),plane:d.get('plane')||'XY'}),'Apply');}
async function pullSelected(distance,source=null){const b=source?.body||one(),index=source?.face??pickedFace(b);if(index===null)throw Error('Select an exact planar face.');return modify(b,'faceExtrude',{faces:[index],distance},'Pull exact planar face');}
function thickenDialog(){const b=one();modal('Thicken face or open shell',note('Creates a solid using the offset skin and joining side faces. A closed solid is not an input to this operation.')+field('thickness','Signed thickness (mm)',2),d=>modify(b,'thicken',{thickness:val(d,'thickness')}),'Thicken');}
function booleanDialog(){const bs=chosenExact(2);modal('Exact Boolean operation',field('operation','Operation','union',{options:[['union','Union'],['subtract','Subtract tools from target'],['intersect','Intersection']]})+field('target','Target body',bs[0].id,{options:bs.map(b=>[b.id,b.name])})+field('keep','Keep tools',false,{type:'checkbox',inline:true})+note('All inputs must be exact B-rep bodies. The entire sequence is committed as one undoable edit.'),async d=>{const check=guard(),target=bs.find(b=>b.id===d.get('target')),tools=bs.filter(b=>b!==target);let result=exactInput(target);for(const b of tools)result=await query('boolean',{shape:result,tool:exactInput(b),operation:d.get('operation')});check();app.document.transact('Exact Boolean '+d.get('operation'),()=>{app.document.find(target.id).solid=solidFromExact(result);if(!d.has('keep'))app.document.remove(tools.map(b=>b.id));});app.setSelection([target.id]);},'Combine');}
function splitDialog(){const b=one();modal('Split exact body',fgrid(field('plane','Cutting plane','XY',{options:['XY','XZ','YZ']}),field('offset','Plane offset (mm)',b.solid.bounds.center[2])),async d=>{let ids=[];await run('split',{shape:exactInput(b),plane:d.get('plane'),offset:val(d,'offset')},'Split exact body',p=>{app.document.remove([b.id]);ids=p.shapes.map((s,i)=>app.document.add(solidFromExact(s),b.name+(i?' −':' +'),b.material,b.component).id);});app.setSelection(ids);},'Split');}
function holeDialog(){const b=one(),bb=b.solid.bounds;modal('Exact cylindrical hole',fgrid(field('radius','Radius (mm)',5,{min:.001}),field('length','Tool length (mm)',Math.max(...bb.size)+10,{min:.001}))+field('center','Tool center',bb.center.join(', '),{type:'text'})+field('axis','Direction','Z',{options:['X','Y','Z']}),async d=>{const check=guard(),center=vec(d.get('center')),axis=d.get('axis'),rotation=axis==='X'?M.rotate([0,1,0],Math.PI/2):axis==='Y'?M.rotate([1,0,0],-Math.PI/2):M.identity();let tool=await query('primitive',{kind:'cylinder',radius:val(d,'radius',.001),height:val(d,'length',.001)});tool.pose=M.mul(M.translate(center),rotation);const result=await query('boolean',{shape:exactInput(b),tool,operation:'subtract'});check();app.document.transact('Exact hole',()=>app.document.find(b.id).solid=solidFromExact(result));app.setSelection([b.id]);},'Cut hole');}
function sewDialog(){const bs=chosenExact();modal('Sew exact faces and shells',note('Sews compatible boundaries. Solid mode requires a closed shell; invalid or disconnected topology is rejected.')+field('solid','Make closed solid',true,{type:'checkbox',inline:true}),async d=>{let id;await run('sew',{shapes:bs.map(exactInput),solid:d.has('solid')},'Sew geometry',p=>{app.document.remove(bs.map(b=>b.id));id=app.document.add(solidFromExact(p),'Sewn shape','aluminum',bs[0].component).id;});app.setSelection([id]);},'Sew');}
function toleranceDialog(){const b=one();modal('Retessellate exact body',note('Only the display mesh changes. The B-rep, engineering references and exact dimensions are preserved.')+fgrid(field('tolerance','Chord tolerance (mm)',.08,{min:.001,max:10}),field('angularTolerance','Angular tolerance (radians)',.18,{min:.02,max:1})),async d=>{const old=b.solid.meta;await run('mesh',{shape:exactInput(b),tolerance:val(d,'tolerance',.001,10),angularTolerance:val(d,'angularTolerance',.02,1)},'Retessellate exact body',p=>{const s=solidFromExact(p);s.meta.referenceKey=old.referenceKey;s.meta.referenceFrame=old.referenceFrame;for(const k of ['surfaceDefinition','sheetDefinition','sheetFlat','bendTable','flatLength','sheetPanelDefinition','sheetPanelLayout','flat','native3dm'])if(old.exact[k]!==undefined)s.meta.exact[k]=structuredClone(old.exact[k]);if(old.exact.native3dm)s.meta.exact.native3dmPose=M.mul(old.exact.pose,old.exact.native3dmPose||M.identity());if(old.exact.surfaceDefinition)s.meta.exact.surfacePose=M.mul(old.exact.pose,old.exact.surfacePose||M.identity());if(old.exact.sheetPose)s.meta.exact.sheetPose=M.mul(old.exact.pose,old.exact.sheetPose);if(old.exact.sheetPanelPose)s.meta.exact.sheetPanelPose=M.mul(old.exact.pose,old.exact.sheetPanelPose);app.document.find(b.id).solid=s;});app.setSelection([b.id]);},'Regenerate mesh');}
function inspector(){const b=one(),e=b.solid.meta.exact,p=transformedExactProperties(b);report('Exact B-rep inspector',`<div class="engineering-metrics"><div><strong>${p.volume.toFixed(4)}</strong><span>VOLUME · mm³</span></div><div><strong>${p.area.toFixed(4)}</strong><span>AREA · mm²</span></div><div><strong>${p.solidCount}</strong><span>VALID SOLIDS</span></div></div>`+note(`${escape(b.name)} · ${e.faces.length} analytic faces · ${e.edges.length} topological edges. Indices are current-topology identifiers, not persistent names. Modeling edits invalidate old selections.`)+table(['Face','Surface','Area mm²','Center (kernel coordinates)','Analytic radius'],e.faces.map(f=>[f.index,f.type,f.area.toFixed(4),f.center.map(x=>x.toFixed(2)).join(', '),f.analytic?.radius??'—']))+table(['Edge','Curve','Length mm','Radius'],e.edges.map(x=>[x.index,x.type,x.length.toFixed(4),x.analytic?.radius??'—']))+note('Topology tables use the serialized shape’s local coordinates; native volume and area above include the instance pose and uniform scale. Display bounds are tessellation-derived.'));}
function supportsFile(name){return /\.(step|stp|iges|igs|brep)$/i.test(name||'');}
async function importFile(file){if(!file||!supportsFile(file.name))throw Error('Choose STEP, IGES or BREP.');if(file.size>32*1024*1024)throw Error('CAD import is limited to 32 MB.');const check=guard(),data=await file.text(),ext=file.name.split('.').at(-1).toLowerCase();let result;if(['iges','igs'].includes(ext)){const bridge=await query('toSTEP',{data},iges);result=await query('importSTEP',{data:bridge.data});}else result=await query(ext==='brep'?'importBREP':'importSTEP',{data});check();let id;app.document.transact('Import '+file.name,()=>{id=app.document.add(solidFromExact(result),file.name.replace(/\.[^.]+$/,''),'aluminum',app.document.components[0]?.id||'parts').id;});app.setSelection([id]);app.renderer.camera.fit(app.document.bounds());app.renderer.request();toast('Imported exact geometry. Assembly hierarchy and semantic PMI are not restored by this translator.');return app.document.find(id);}
function fileDialog(){const input=document.createElement('input');input.type='file';input.accept='.step,.stp,.iges,.igs,.brep';input.addEventListener('change',()=>importFile(input.files[0]).catch(e=>toast(e.message,true)));input.click();}
function exportDialog(){const bs=allExact();modal('Export exact CAD geometry',field('format','Format','step',{options:[['step','STEP — analytic B-rep, names and colors'],['iges','IGES — geometry only'],['brep','OpenCascade BREP — one body']]})+note('STEP/IGES export uses the analytic source, not tessellated triangles. Proprietary native CAD formats require a separate licensed translator and are not available here. IGES uses a separately loaded compatibility worker.'),async d=>{const type=d.get('format');let output;if(type==='brep'){if(bs.length!==1)throw Error('BREP export requires one selected body.');const p=await query('mesh',{shape:exactInput(bs[0])});output={data:p.brep,mime:'application/octet-stream'};}else{output=await query('exportSTEP',{shapes:bs.map(exactInput),bridge:type==='iges'});if(type==='iges')output=await query('toIGES',{data:output.data},iges);}download(`${app.document.name}.${type}`,output.data,output.mime||'text/plain');},'Export');}
function sheetDialog(){const b=selected().length===1?selected()[0]:null,e=b?.solid.meta.exact,def=e?.sheetDefinition||defaultSheet;modal(e?.sheetDefinition?'Edit developable sheet':'Create multibend sheet',note('Lengths are straight tangent-to-tangent flange lengths, not outside dimensions. Signed bends use degrees. Circular punches lie fully on flat flanges. K-factor controls bend allowance; no forming-strain simulation is implied.')+textArea('definition','Sheet definition (mm)',def,15)+field('flat','Create unfolded',e?.sheetFlat||false,{type:'checkbox',inline:true}),async d=>{const definition=readJSON(d,'definition'),args={definition,flat:d.has('flat')};if(e?.sheetDefinition){if(b.locked)throw Error('Unlock the body.');args.pose=M.mul(e.pose,e.sheetPose||M.identity());await run('sheetMetal',args,'Edit sheet',p=>app.document.find(b.id).solid=solidFromExact(p));app.setSelection([b.id]);}else await create('sheetMetal',args,'Multibend sheet');},'Build sheet',true);}
async function unfold(){const b=one(),e=b.solid.meta.exact;if(!e.sheetDefinition)throw Error('Select an exact multibend sheet. Topology-changing edits remove the unfold definition.');await run('sheetMetal',{definition:e.sheetDefinition,flat:!e.sheetFlat,pose:M.mul(e.pose,e.sheetPose||M.identity())},e.sheetFlat?'Refold exact sheet':'Unfold exact sheet',p=>app.document.find(b.id).solid=solidFromExact(p));app.setSelection([b.id]);}
function sheetExport(){const b=one(),def=b.solid.meta.exact.sheetDefinition;if(!def)throw Error('Select an exact sheet definition.');const layout=sheetLayout(def);modal('Developed sheet and bend schedule',table(['Bend','Angle','Radius','Allowance','Centerline'],layout.bendTable.map((x,i)=>[i+1,x.angle,x.insideRadius,x.allowance,x.centerLine]))+note(`Developed length ${layout.flatLength.toFixed(4)} mm · K=${def.kFactor}. Flat geometry includes punches and bend centerlines.`)+field('format','Output','svg',{options:['svg','dxf','csv']}),d=>{const format=d.get('format'),data=format==='svg'?sheetSVG(def):format==='dxf'?sheetDXF(def):sheetBendCSV(def);download(`${b.name}-flat.${format}`,data,format==='svg'?'image/svg+xml':'text/plain');},'Export flat');}
