function limitations(){report('Avolith precision and engineering capabilities',`<div class="engineering-heading">Analytic modeling. Explicit boundaries.</div>${note('Native WebGPU rendering with analytic B-rep solids, rational NURBS faces and a cancellable worker-based OpenCascade kernel. STEP, IGES and BREP exchange operate on exact geometry. The original faceted engine remains available for mesh workflows.')}${table(['Area','Delivered boundary'],[['Exact editing','Constant-radius fillets, equal chamfers, face-removal shelling, draft, planar face-prism Pull, offsets and thickening; kernel rejects unsupported topology.'],['NURBS','Weighted nonperiodic tensor-product surfaces with editable poles, knots and degrees. Not arbitrary trim-loop or continuity-network editing.'],['Sheet metal','Developable multibend constant-width strips and flat-flange round punches. Not hems, beads, arbitrary corner relief, forming dies or springback.'],['Assembly','10 rigid-body mate types, local datums, ground state, residual/rank and DOF reporting. Not dynamics or universal robust mechanism solving.'],['Drafting / PMI','True HLR views, dimensional and semantic FCF/datum annotations, SVG and JSON. Not certified ASME/ISO interpretation or semantic STEP-PMI exchange.'],['Preparation','Topology and small-feature checks, sampled walls, native clearance/overlap, surface VTK and shell skins. Not volume meshing, simulation solution or certification.'],['CAD translators','STEP / IGES / BREP geometry; hierarchy and PMI import are not restored. Proprietary native translators are not installed.']])}${warning('No production, manufacturing, simulation or safety certification is claimed. Validate tolerances, engineering requirements and exports independently.')}`);}
